export function arkDefinition(key:string):ArkCardDefinition {const c=ARK_CARDS.find(c=>c.key===key);if(!c)throw new Error('Unknown Ark card definition.');return c;}
export function arkProject(key:string):ArkProjectDefinition {const c=ARK_PROJECTS.find(c=>c.key===key);if(!c)throw new Error('Unknown Ark project definition.');return c;}
export function arkCardName(key:string):string{return ARK_CARDS.find(c=>c.key===key)?.name??ARK_PROJECTS.find(c=>c.key===key)?.name??ARK_GOALS.find(c=>c.key===key)?.name??key;}
